package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class GitHubLearningRouteTest {
 @Test void newTypedRoutesKeepInternalReferenceHiddenAndMethodsExact(){String id="019a0808-1234-7000-8000-000000000001",base="/api/spaces/"+id,root=base+"/roadmaps/"+id+"/github-evidence",item=root+"/"+id;for(String p:new String[]{root,item,item+"/revisions",item+"/study-session",item+"/study-session/revisions",base+"/github-learning-evidence"})assertEquals("learning",GatewayRoute.select("GET",p).service());assertEquals("learning",GatewayRoute.select("POST",root).service());assertEquals("learning",GatewayRoute.select("PUT",item).service());assertEquals("learning",GatewayRoute.select("DELETE",item).service());assertEquals("learning",GatewayRoute.select("PUT",item+"/study-session").service());for(String method:new String[]{"GET","POST","PUT","DELETE"})assertNull(GatewayRoute.select(method,base+"/github/repositories/"+id+"/commits/"+id+"/reference"));for(String method:new String[]{"POST","DELETE","PATCH"})assertNull(GatewayRoute.select(method,item+"/study-session"));assertNull(GatewayRoute.select("PUT",root));assertNull(GatewayRoute.select("DELETE",item+"/revisions"));}
}
